def Run(ctx, a):
    text = fs.read("index.html").text
    script = text.split("<script>", 1)[1].split("</script>", 1)[0]

    # Lightweight delimiter balance check that skips JS strings and comments.
    stack, i, n = [], 0, len(script)
    pairs = {")": "(", "]": "[", "}": "{"}
    while i < n:
        c = script[i]
        if c in "'\"`":
            q, i = c, i + 1
            while i < n:
                if script[i] == "\\":
                    i += 2
                    continue
                if script[i] == q:
                    i += 1
                    break
                i += 1
            continue
        if c == "/" and i + 1 < n and script[i + 1] == "/":
            i = script.find("\n", i)
            i = n if i == -1 else i
            continue
        if c == "/" and i + 1 < n and script[i + 1] == "*":
            j = script.find("*/", i + 2)
            i = n if j == -1 else j + 2
            continue
        if c in "([{":
            stack.append(c)
        elif c in ")]}":
            if not stack or stack.pop() != pairs[c]:
                return {"js_balanced": False, "reason": "mismatch at char %d" % i}
        i += 1

    class Tags(HTMLParser):
        def __init__(self):
            super().__init__()
            self.stack, self.errors = [], []
            self.void = {"meta", "link", "br", "hr", "img", "input", "source", "area", "base", "col", "embed", "param", "track", "wbr"}
        def handle_starttag(self, tag, attrs):
            if tag not in self.void:
                self.stack.append(tag)
        def handle_endtag(self, tag):
            if tag in self.void:
                return
            if not self.stack or self.stack[-1] != tag:
                self.errors.append("unexpected </%s>" % tag)
            else:
                self.stack.pop()

    p = Tags()
    p.feed(text)
    return {
        "js_balanced": not stack,
        "js_unclosed": stack,
        "html_unclosed": p.stack,
        "html_errors": p.errors,
        "script_lines": len(script.splitlines()),
        "first_line": text.splitlines()[0],
        "last_line": text.splitlines()[-1],
    }

