<body>
<main>
  <h1>To-Do</h1>

  <form id="add-form" autocomplete="off">
    <label class="sr-only" for="new-todo">New task</label>
    <input id="new-todo" type="text" placeholder="What needs doing?" maxlength="200" required>
    <button type="submit" id="add-btn" disabled>Add</button>
  </form>

  <ul id="list" aria-live="polite"></ul>
  <p class="empty" id="empty">Nothing here yet. Add your first task above.</p>

  <div class="bar">
    <span id="count">0 items</span>
    <button type="button" class="clear" id="clear-done" disabled>Clear completed</button>
  </div>
</main>

<script>
(function () {
  "use strict";

  var STORAGE_KEY = "todo.items.v1";

  var form = document.getElementById("add-form");
  var input = document.getElementById("new-todo");
  var addBtn = document.getElementById("add-btn");
  var list = document.getElementById("list");
  var empty = document.getElementById("empty");
  var count = document.getElementById("count");
  var clearDone = document.getElementById("clear-done");

  // items: [{ id: string, text: string, done: boolean }]
  var items = [];

  function load() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return [];
      var parsed = JSON.parse(raw);
      if (!Array.isArray(parsed)) return [];
      return parsed
        .filter(function (it) {
          return it && typeof it.text === "string";
        })
        .map(function (it) {
          return {
            id: String(it.id || makeId()),
            text: it.text,
            done: !!it.done
          };
        });
    } catch (e) {
      console.warn("Could not read saved todos:", e);
      return [];
    }
  }

  function save() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(items));
    } catch (e) {
      console.warn("Could not save todos:", e);
    }
  }

  function makeId() {
    if (window.crypto && typeof crypto.randomUUID === "function") {
      return crypto.randomUUID();
    }
    return Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
  }

  function render() {
    list.textContent = "";

    items.forEach(function (item) {
      var li = document.createElement("li");
      if (item.done) li.className = "done";

      var label = document.createElement("label");

      var box = document.createElement("input");
      box.type = "checkbox";
      box.checked = item.done;
      box.setAttribute("aria-label", item.done ? "Mark not done" : "Mark done");
      box.addEventListener("change", function () {
        toggle(item.id);
      });

      var span = document.createElement("span");
      span.className = "text";
      span.textContent = item.text;

      label.appendChild(box);
      label.appendChild(span);

      var del = document.createElement("button");
      del.type = "button";
      del.className = "del";
      del.textContent = "\u00d7";
      del.title = "Delete";
      del.setAttribute("aria-label", "Delete " + item.text);
      del.addEventListener("click", function () {
        remove(item.id);
      });

      li.appendChild(label);
      li.appendChild(del);
      list.appendChild(li);
    });

    empty.hidden = items.length > 0;

    var remaining = items.filter(function (it) { return !it.done; }).length;
    var doneCount = items.length - remaining;
    count.textContent =
      items.length === 0
        ? "0 items"
        : remaining + (remaining === 1 ? " item left" : " items left") +
          (doneCount ? " \u00b7 " + doneCount + " done" : "");

    clearDone.disabled = doneCount === 0;
  }

  function commit() {
    save();
    render();
  }

  function add(text) {
    var trimmed = text.trim();
    if (!trimmed) return;
    items.push({ id: makeId(), text: trimmed, done: false });
    commit();
  }

  function toggle(id) {
    items = items.map(function (it) {
      return it.id === id ? { id: it.id, text: it.text, done: !it.done } : it;
    });
    commit();
  }

  function remove(id) {
    items = items.filter(function (it) { return it.id !== id; });
    commit();
  }

  function clearCompleted() {
    items = items.filter(function (it) { return !it.done; });
    commit();
  }

  form.addEventListener("submit", function (e) {
    e.preventDefault();
    add(input.value);
    input.value = "";
    syncAddBtn();
    input.focus();
  });

  input.addEventListener("input", syncAddBtn);

  function syncAddBtn() {
    addBtn.disabled = input.value.trim() === "";
  }

  clearDone.addEventListener("click", clearCompleted);

  // Keep multiple open tabs in sync.
  window.addEventListener("storage", function (e) {
    if (e.key === STORAGE_KEY) {
      items = load();
      render();
    }
  });

  items = load();
  render();
  syncAddBtn();
})();
</script>
</body>
</html>
