import agent


def Run(ctx, a):
    # Detached subagent: launch, do not wait.
    detached = agents.tasks.start(
        "build",
        "Read README.md and report its first line in your final answer.",
        "read-readme",
    )

    # Independent filesystem calls, run concurrently.
    jobs = [
        agent.jobs.start(fs.read, "README.md"),
        agent.jobs.start(fs.glob, "*"),
    ]
    job_results = []
    for job in jobs:
        try:
            job_results.append({"ok": True, "result": job.result()})
        except AgentError as error:
            job_results.append({"ok": False, "kind": error.kind, "message": error.message})

    return {
        "detached_job": {
            "session_id": detached.session_id,
            "job_id": detached.job_id,
            "status": detached.status,
        },
        "fs_results": job_results,
    }

